import { Table, useTableController, type Key } from '@tale-ui/react/table';

const people = [
  { id: '1', name: 'Alice', role: 'Designer' },
  { id: '2', name: 'Bob', role: 'Engineer' },
  { id: '3', name: 'Carol', role: 'Manager' },
];

export function SortablePeopleTable() {
  const controller = useTableController({
    tableId: 'people',
    defaultSortDescriptor: { column: 'name', direction: 'ascending' },
  });
  const rows = controller.sorting.sortRows(people, (left, right, column: Key) => {
    if (column === 'role') return left.role.localeCompare(right.role);
    return left.name.localeCompare(right.name);
  });

  return (
    <Table.Root {...controller.tableProps} aria-label="People">
      <Table.Header>
        <Table.Column id="name" isRowHeader allowsSorting>
          Name
        </Table.Column>
        <Table.Column id="role" allowsSorting>
          Role
        </Table.Column>
      </Table.Header>
      <Table.Body>
        {rows.map((row) => (
          <Table.Row key={row.id} id={row.id}>
            <Table.Cell>{row.name}</Table.Cell>
            <Table.Cell>{row.role}</Table.Cell>
          </Table.Row>
        ))}
      </Table.Body>
    </Table.Root>
  );
}
